package org.diy.liferecorder;
import android.content.Context;import android.graphics.*;import android.view.View;import org.json.*;import java.util.*;
/** Small plot of observed samples; missing values never become zero. */
final class SensorTraceView extends View {
 private final java.util.SortedMap<Long,Float> points=new java.util.TreeMap<>();private final Paint paint=new Paint(3);private final int color;
 SensorTraceView(Context c,RecordStore store,String source,String type,int color){super(c);this.color=color;setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_NO);try{JSONArray rows=source==null?store.rows("SELECT payload FROM context WHERE created>=? ORDER BY created DESC LIMIT 32",String.valueOf(day())):store.rows("SELECT payload FROM context WHERE source=? ORDER BY created",source);for(int n=0;n<rows.length();n++)for(String line:rows.getJSONObject(n).optString("payload").split("\n")){try{JSONObject r=new JSONObject(line);if(!r.optString("type").equals(type)||!r.has("value")||r.isNull("value"))continue;long at=r.optLong("observed_at_epoch_ms",r.optLong("at_epoch_ms"));float value=(float)r.optDouble("value");if(at>0&&Float.isFinite(value))points.put(at,value);}catch(Exception ignored){}}}catch(Exception ignored){}}
 private long day(){Calendar c=Calendar.getInstance();c.set(Calendar.HOUR_OF_DAY,0);c.set(Calendar.MINUTE,0);c.set(Calendar.SECOND,0);return c.getTimeInMillis();}
 protected void onDraw(Canvas c){super.onDraw(c);paint.setColor(color);paint.setStrokeWidth(getResources().getDisplayMetrics().density*1.4f);paint.setStrokeCap(Paint.Cap.ROUND);paint.setStyle(Paint.Style.STROKE);if(points.isEmpty())return;if(points.size()==1){c.drawCircle(getWidth()/2f,getHeight()/2f,2*getResources().getDisplayMetrics().density,paint);return;}float min=Collections.min(points.values()),max=Collections.max(points.values());long first=points.firstKey(),last=points.lastKey();Path path=new Path();int index=0;for(Map.Entry<Long,Float> entry:points.entrySet()){float x=4+(getWidth()-8)*(entry.getKey()-first)/(float)Math.max(1,last-first);float y=max==min?getHeight()/2f:4+(getHeight()-8)*(1-(entry.getValue()-min)/(max-min));if(index++==0)path.moveTo(x,y);else path.lineTo(x,y);}c.drawPath(path,paint);}
}
